173	// A negative budget means no tool rounds; a non-finite one, NaN included, falls back to the default rather than never ending.
174	function normalizeToolRounds(value: number | undefined): number {
175	  if (value === undefined || !Number.isFinite(value)) return DEFAULT_MAX_TOOL_ROUNDS;
176	  return Math.max(0, Math.floor(value));
177	}
178	
179	// Gates execution, not the provider call: a round nobody can read is never run, and the call that read the last one already has.
180	function budgetSpent(round: number, maxToolRounds: number, pendingToolCalls: ToolCall[]): boolean {
181	  if (round < maxToolRounds) return false;
182	  log.warn('orchestrator', 'tool budget exhausted', {
183	    maxToolRounds,
184	    requestedTools: pendingToolCalls.map(tc => tc.name),
185	  });
186	  return true;
187	}
188	
189	// The stop always follows the text: the round's own stop already committed its entry, and a bare text chunk would open one never committed.
190	async function* closeExhaustedTurn(
191	  session: ChatSession,
192	  budget: ToolBudgetInfo,
193	  hook?: OnToolBudgetExhausted
194	): AsyncGenerator<MessageChunk, string> {
195	  const sentence = (hook ? await hook(session, budget) : undefined) ?? '';
196	  if (sentence !== '') yield {type: 'text', text: sentence};
197	  yield {type: 'stop', stopReason: TOOL_BUDGET_EXHAUSTED};
198	  return sentence;
199	}
200	
201	interface RoundOutcome {
202	  stopReason: string;
203	  text: string;
204	  usage?: UsageMetadata;
205	}
206	
207	// `yield*` in the caller evaluates to this return, so the round's totals come back as data.
208	async function* streamRound(
209	  provider: AIProvider,
210	  request: SendMessageParams,
211	  pendingToolCalls: ToolCall[]
212	): AsyncGenerator<MessageChunk, RoundOutcome> {
213	  let stopReason = '';
214	  let text = '';
215	  let usage: UsageMetadata | undefined;
216	
217	  for await (const chunk of provider.sendMessage(request)) {
218	    yield chunk;
219	    collectToolCalls(chunk, pendingToolCalls);
220	    stopReason = extractStopReason(chunk) ?? stopReason;
